/**
 * Apply the query allowlist only to Agent scopes that select `crm-query`.
 *
 * Agent-create listeners and preset composition are process-wide services.
 * The restriction and guard belong to each matching Agent scope.
 *
 * The allowed, hidden and explicitly denied tool names are generated from
 * `config/query-agent-tool-policy.v1.json` by `build.mjs`; do not copy them
 * into this module.
 */
// Generated by `node build.mjs` from `config/query-agent-tool-policy.v1.json`.
// Do not edit by hand.
const toolPolicy = Object.freeze({
  schema_version: "query-agent-tool-policy/v1",
  preset_id: "crm-query",
  allowed: Object.freeze([
    "query_crm_dashboard_snapshot",
    "query_crm_warehouse_snapshot",
    "query_crm_dashboard_gsv",
    "query_crm_dashboard_purchases",
    "query_crm_product_customer_cohorts",
    "query_crm_rfm_snapshot",
    "query_crm_metrics_v1",
    "query_crm_dashboard_readiness",
    "query_crm_dashboard_membership",
    "query_crm_dashboard_net_gsv",
    "crm_metrics_capabilities",
    "crm_service_health",
    "weknora_search",
    "weknora_read_document",
    "free_html_page_generate",
  ]),
  hidden_inherited: Object.freeze([
    "bash",
    "pwsh",
    "terminal_open",
    "terminal_send",
    "terminal_read",
    "terminal_signal",
    "terminal_close",
    "terminal_list",
    "read",
    "write",
    "edit",
    "glob",
    "grep",
    "read_image",
    "web_search",
    "web_fetch",
    "run_code",
    "subagent",
    "list_subagent_models",
    "spawn_teammate",
    "send_message",
    "list_agents",
    "interrupt_agent",
    "wait_agent",
    "team_task_create",
    "team_task_get",
    "team_task_list",
    "team_task_update",
    "todo_write",
    "exit_plan_mode",
    "skill",
  ]),
  official_denied: Object.freeze([
    "ask_user_question",
    "cordis_inspect_list",
    "cordis_inspect_query",
    "create_goal",
    "create_worktree",
    "get_goal",
    "job_kill",
    "job_list",
    "job_output",
    "list_mcp_resource_templates",
    "list_mcp_resources",
    "load_workspace_dependencies",
    "lsp",
    "plugin_manager",
    "plugin_market",
    "present",
    "ralph",
    "read_mcp_resource",
    "schedule_create",
    "schedule_delete",
    "schedule_list",
    "schedule_update",
    "session_event_read",
    "session_event_search",
    "session_event_trace",
    "session_search",
    "session_trace",
    "stagehand_act",
    "stagehand_extract",
    "stagehand_navigate",
    "stagehand_observe",
    "stagehand_screenshot",
    "stagehand_tabs",
    "str_replace_editor",
    "update_goal",
    "workflow",
    "working_directory",
  ]),
})

export const name = 'query-tool-policy';
export const inject = ['agentPresets', 'agents', 'tools'];
export const queryPresetId = toolPolicy.preset_id;
export const queryToolAllowlist = toolPolicy.allowed;
export const hiddenInheritedTools = toolPolicy.hidden_inherited;
export const officialDeniedTools = toolPolicy.official_denied;
const allowedTools = new Set(queryToolAllowlist);
const hiddenTools = new Set(hiddenInheritedTools);
export function apply(ctx) {
    const restrictions = new Map();
    const agentIdOf = (agent) => agent?.id ?? agent?.session?.id;
    const release = (target) => {
        const agentId = typeof target === 'string' ? target : agentIdOf(target);
        if (agentId === undefined)
            return;
        restrictions.get(agentId)?.();
        restrictions.delete(agentId);
    };
    const enforce = (agent) => {
        const agentId = agentIdOf(agent);
        if (agentId === undefined || agent === undefined || agent.ctx === undefined)
            return;
        if (ctx.agentPresets.composedPreset(agent.ctx) !== queryPresetId) {
            release(agentId);
            return;
        }
        if (restrictions.has(agentId))
            return;
        // Hide known inherited shell, filesystem and collaboration tools without
        // replacing the preset's scoped business tools. The guard is the final
        // deny-by-default boundary for any future tool that appears in schema.
        const agentContext = agent.ctx;
        const visibleNames = agentContext.tools.schemas().map(tool => tool.name);
        const deny = visibleNames.filter(tool => hiddenTools.has(tool));
        const dispose = agentContext.effect(() => {
            const liftMask = deny.length > 0 ? agentContext.tools.restrict({ deny }) : undefined;
            const liftGuard = agentContext.tools.guard(execution => (allowedTools.has(execution.name)
                ? undefined
                : `CRM_QUERY_TOOL_NOT_ALLOWED: ${execution.name}`));
            return () => {
                liftGuard();
                liftMask?.();
            };
        });
        if (typeof dispose === 'function')
            restrictions.set(agentId, dispose);
    };
    return ctx.effect(() => {
        const created = ctx.on('agent/created', ({ agent }) => enforce(agent));
        // Selecting a preset on a blank session rebinds the Agent in place; DSH
        // emits this event instead of creating a new Agent.
        const selected = ctx.on('agent-preset/selected', sessionId => {
            const agent = ctx.agents.get(sessionId);
            if (agent !== undefined)
                enforce(agent);
        });
        const disposed = ctx.on('agent/disposed', ({ agent }) => release(agent));
        return () => {
            created?.();
            selected?.();
            disposed?.();
            for (const agentId of [...restrictions.keys()])
                release(agentId);
        };
    });
}
